// 1. Acceder al contenido de la IA (Viene del nodo anterior)
const aiOutput = $json.output?.[0]?.content?.[0]?.text?.message;

if (!aiOutput) {
  throw new Error("No se encontró contenido en la respuesta de la IA.");
}

try {
  // 2. Parsear el JSON generado por la IA
  const cleanJson = JSON.parse(aiOutput);

  // 3. Obtener las columnas reales desde el nodo Get
  const getOutput = $("Get").all();
  const realColumns = [...new Set(getOutput.map(item => item.json.column_name))];

  if (realColumns.length === 0) {
    throw new Error("No se pudieron recuperar las columnas del nodo 'Get'.");
  }

  const modelName = $("Get Model Name").first().json.model_name;

  // SECURITY: tenant isolation is fail-closed. Only tenant-scoped tables may be auto-registered.
  if (!realColumns.includes('tenant_id') && !realColumns.includes('id_company')) {
    throw new Error('Tabla sin columna tenant_id/id_company: debe registrarse manualmente.');
  }

  // SECURITY: internal tables are never auto-registered.
  if (/^(crud_|pg_|n8n)/i.test(modelName) || /_backup_/i.test(modelName)) {
    throw new Error('Tabla reservada: debe registrarse manualmente.');
  }

  // 4. VALIDACIÓN DE LA PRIMARY KEY (la IA solo sugiere; se valida contra columnas reales)
  let finalPK = cleanJson.primary_key;
  if (!realColumns.includes(finalPK)) {
    finalPK = realColumns.find(c => c.toLowerCase() === 'id' || c.toLowerCase().endsWith('_id'))
              || (modelName === 'users' && realColumns.includes('email') ? 'email' : null)
              || realColumns[0];
  }

  // SECURITY: everything below comes from the real catalog, never from the model output,
  // because these values end up interpolated into SQL (INSERT here, JOINs later in Build Query).
  const ident = /^[A-Za-z_][A-Za-z0-9_]{0,62}$/;
  if (![modelName, finalPK, ...realColumns].every(v => ident.test(String(v)))) {
    throw new Error('Nombre de tabla o columna no permitido para auto-registro.');
  }

  const seen = new Set();
  const realJoins = getOutput
    .map(i => i.json)
    .filter(r => r.foreign_table && r.foreign_column)
    .map(r => ({ table: r.foreign_table, own_col: r.column_name, foreign_col: r.foreign_column }))
    .filter(j => { const k = JSON.stringify(j); if (seen.has(k)) return false; seen.add(k); return true; });
  if (!realJoins.every(j => ident.test(j.table) && ident.test(j.own_col) && ident.test(j.foreign_col))) {
    throw new Error('Relación con nombre no permitido para auto-registro.');
  }

  const toType = (dt) => /int|numeric|decimal|real|double|serial/i.test(dt || '') ? 'number'
                       : (/bool/i.test(dt || '') ? 'boolean' : 'string');
  const schemaJson = {};
  getOutput.forEach(i => {
    const r = i.json;
    if (!schemaJson[r.column_name]) schemaJson[r.column_name] = { type: toType(r.data_type), required: false };
  });

  // 5. Retornar el objeto limpio para el INSERT
  return [{
    json: {
      table_name: modelName,
      primary_key: finalPK,
      allowed_fields: realColumns,
      schema_json: schemaJson,
      joins: realJoins,
      allowed_ops: ['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'GETALL', 'GETONE'],
      hooks: { pre: [], post: [] }
    }
  }];

} catch (e) {
  throw new Error("Error al procesar configuración de IA: " + e.message);
}

let role = null;
let email = null;
const modelName = $("Get Model Name").first().json.model_name;

// Read identity from the verified token (never from the request body)
try {
  const verifyTokenNode = $("Verify Token").first();
  if (verifyTokenNode && verifyTokenNode.json.status === "success") {
    const tokenUser = verifyTokenNode.json.data?.user || {};
    // Role of the user IN THE REQUESTED COMPANY (user_companies), not the role frozen in the JWT at login.
    role = $("Get Membresia").first().json.role;
    // The JWT issued by jwt-service carries the email under the `user` claim.
    email = tokenUser.user ?? tokenUser.email ?? null;
  }
} catch (error) {
  // Public path: 'Verify Token' did not run; role stays null and is validated below.
}

// Public read-only access to companys (login tenant picker)
if (!role && modelName === 'companys') {
  role = 'CUSTOMER';
}

if (!role) {
  return [{
    json: {
      error: true,
      status: 401,
      message: "Acceso denegado: Se requiere autenticación o modelo no público.",
      code: "NO_ROLE"
    }
  }];
}

return [{
  json: {
    user: {
      role: role.toUpperCase(),
      email
    }
  }
}];

// 1. Obtener datos de entrada
const authContext = $json;

// 2. Acceder al Webhook original de forma segura (usando .first() para saltar ramas)
const webhookData = $('WebhookCRUD').first().json;
const body = webhookData.body || {};

// Capturamos 'action' o 'operation' (Angular mandó 'action': 'list')
const operationRaw = (body.action || body.operation || "").toLowerCase();

// VALIDACIÓN DE OPERACIÓN FALTANTE
if (!operationRaw) {
  return [{
    json: {
      error: true,
      status: 400,
      message: "No se especificó ninguna acción u operación (list, insert, etc.)",
      code: "MISSING_OPERATION"
    }
  }];
}

const userRole = authContext.user?.role;
if (!userRole) {
  return [{
    json: {
      error: true,
      status: 401,
      message: "Acceso Denegado: Rol de usuario no definido.",
      code: "AUTH_ERROR"
    }
  }];
}

// 3. Mapeo de operaciones
const opMapping = { 
    'list': 'getall',
    'getall': 'getall',
    'getone': 'getone',
    'insert': 'insert',
    'update': 'update',
    'delete': 'delete',
    'select': 'getall',
    'call_sp': 'call_sp'
};

const opToValidate = opMapping[operationRaw] || 'getall';

// Mapeo para revisar permisos en DB (la DB sí usa select/insert/update/delete)
// un SP invocado vía call_sp es semánticamente una operación de escritura:
const opForSecurity = ['getall', 'getone'].includes(opToValidate)
  ? 'select'
  : (opToValidate === 'call_sp' ? 'insert' : opToValidate);

// 4. Obtener la configuración del modelo
const modelConfig = $('Schema Validate').first().json;

// 5. Verificación de permisos de Operación
const allowedOps = Array.isArray(modelConfig.allowed_ops) ? modelConfig.allowed_ops : [];
const isOpAllowed = allowedOps.map(op => op.toLowerCase()).includes(opForSecurity);

if (!isOpAllowed) {
  return [{ json: { error: true, status: 403, message: `Operación no permitida para este modelo.` } }];
}

// 6. Verificación de Rol contra la DB
const roleKey = `allowed_roles_${opForSecurity}`;

const allowedRolesStr = modelConfig[roleKey] || ""; // Si no existe la columna, queda vacío
if (!allowedRolesStr) {
    return [{
        json: {
            error: true,
            status: 500,
            message: `Configuración de seguridad faltante: No se encontró la columna ${roleKey} en la tabla crud_models.`,
            code: "CONFIG_ERROR"
        }
    }];
}

const allowedRolesList = allowedRolesStr.split(',').map(r => r.trim().toUpperCase());
if (!allowedRolesList.includes(userRole.toUpperCase())) {
  return [{
    json: {
      error: true,
      status: 403,
      message: `Prohibido: El rol '${userRole}' no tiene permiso para '${operationRaw.toUpperCase()}'`,
      code: "SECURITY_VALIDATION"
    }
  }];
}

// TODO OK: Retornar configuración con bandera de éxito
return [{
  json: {
    ...modelConfig,
    user_role: userRole,
    // Actor identity comes ONLY from the verified JWT, never from the request body.
    user_email: authContext.user?.email ?? null,
    operation: opToValidate,
    error: false
  }
}];

const crypto = require('crypto');

// Capturamos los datos directamente de los nodos anteriores
const config = $('Security Validation').first().json;
const webhookData = $('WebhookCRUD').first().json; // Obtenemos el payload completo
const body = webhookData.body || {};
const headers = webhookData.headers || {};
const operation = (config.operation || '').toLowerCase();
const table = config.table_name;

// 🚀 FIX: Soportar "filter" en singular y aislar el payload
// Hacemos una copia profunda (JSON.parse) para no mutar el objeto original
let fields = body.filter || body.filters || body.fields || JSON.parse(JSON.stringify(body));

// 🛡️ SECURITY PATCH: Aislamiento Multi-Tenant (Zero-Trust)
// Solo inyectamos tenant_id si el modelo realmente tiene esa columna
const tenantIdHeader = headers['x-tenant-id'];
const modelHasTenantId = (config.allowed_fields || []).includes('tenant_id');
const modelHasIdCompany = (config.allowed_fields || []).includes('id_company');
if (tenantIdHeader && modelHasTenantId) {
    fields['tenant_id'] = tenantIdHeader;
} else if (tenantIdHeader && modelHasIdCompany) {
    fields['id_company'] = tenantIdHeader;
}
const joins = config.joins || [];
const buildJoins = () => {
    if (!joins.length) return '';
    return joins.map(j => {
        const myCol = j.own_col || j.localField;
        const otherCol = j.foreign_col || j.foreignField || 'id';
        return ` LEFT JOIN ${j.table} ON ${table}.${myCol} = ${j.table}.${otherCol}`;
    }).join(' ');
};

const buildSelectFields = () => {
    if (!joins.length) return `${table}.*`;
    let select = `${table}.*`;
    joins.forEach(j => { select += `, row_to_json(${j.table}.*) as ${j.table}_data`; });
    return select;
};

const processValue = (key, value) => {
    if (key === 'password' && value) return crypto.createHash('sha256').update(value).digest('hex');
    return value;
};

// Sanitización de paginación
const sanitizePaginationParams = (limitInput, offsetInput) => {
    let limit = 1500;
    let offset = 0;
    if (limitInput) {
        const parsedLimit = parseInt(limitInput, 10);
        if (!isNaN(parsedLimit) && parsedLimit > 0) limit = Math.min(parsedLimit, 2000);
    }
    if (offsetInput) {
        const parsedOffset = parseInt(offsetInput, 10);
        if (!isNaN(parsedOffset) && parsedOffset >= 0) offset = parsedOffset;
    }
    return { limit, offset };
};

let query = '';
let values = [];

switch (operation) {
    case 'insert': {
        const allowedFields = config.allowed_fields || [];
        const insertFields = [];
        const placeholders = [];
        let paramIndex = 1;

        Object.entries(fields).forEach(([key, value]) => {
            if (allowedFields.includes(key)) {
                insertFields.push(key);
                placeholders.push(`$${paramIndex++}`);
                values.push(processValue(key, value));
            }
        });

        if (insertFields.length === 0) throw new Error("No hay campos válidos para insertar.");

        // Obtener la PK configurada (soporta simples y compuestas separadas por coma)
        const primaryKeyStr = config.primary_key || 'id';
        const pkList = primaryKeyStr.split(',').map(k => k.trim());

        // Filtrar campos para el DO UPDATE SET (excluimos URLs, fechas estáticas y las columnas que componen la PK)
        const updateParts = insertFields
            .filter(f => f !== 'url' && f !== 'created_at' && !pkList.includes(f))
            .map(f => `${f} = EXCLUDED.${f}`);

        if (updateParts.length > 0) {
            query = `INSERT INTO ${table} (${insertFields.join(', ')}) VALUES (${placeholders.join(', ')}) ON CONFLICT (${primaryKeyStr}) DO UPDATE SET ${updateParts.join(', ')} RETURNING *;`;
        } else {
            query = `INSERT INTO ${table} (${insertFields.join(', ')}) VALUES (${placeholders.join(', ')}) ON CONFLICT (${primaryKeyStr}) DO NOTHING RETURNING *;`;
        }
        break;
      }
      case 'update': {
        const primaryKeyStr = config.primary_key || 'id';
        const pkList = primaryKeyStr.split(',').map(k => k.trim());
        // SECURITY: tenant columns are never updatable; they scope the WHERE clause instead.
        const tenantCols = ['tenant_id', 'id_company'];

        const updateParts = [];
        let paramIndex = 1;

        Object.entries(fields).forEach(([key, value]) => {
            if ((config.allowed_fields || []).includes(key) && !pkList.includes(key) && !tenantCols.includes(key)) {
                if (key === 'password' && (!value || value === '')) return;
                updateParts.push(`${key} = $${paramIndex++}`);
                values.push(processValue(key, value));
            }
        });

        if (updateParts.length === 0) throw new Error("No hay campos válidos para actualizar.");

        const whereParts = [];
        pkList.forEach(pkField => {
            const idVal = body[pkField] ?? fields[pkField];
            if (idVal === undefined || idVal === null) {
                throw new Error(`UPDATE requiere el valor de la llave primaria (${pkField}).`);
            }
            whereParts.push(`${pkField} = $${paramIndex++}`);
            values.push(idVal);
        });

        // 🛡️ SECURITY PATCH: Multi-tenant isolation on UPDATE (fail-closed), same rule as GETONE/DELETE.
        // A record of another tenant simply matches zero rows ("No se actualizó ningún registro").
        if (table !== 'users' && (modelHasTenantId || modelHasIdCompany)) {
            if (!tenantIdHeader) throw new Error('x-tenant-id requerido para actualizar este modelo.');
            const tenantCol = modelHasTenantId ? 'tenant_id' : 'id_company';
            whereParts.push(`${tenantCol} = $${paramIndex++}`);
            values.push(tenantIdHeader);
        }

        query = `UPDATE ${table} SET ${updateParts.join(', ')} WHERE ${whereParts.join(' AND ')} RETURNING *;`;
        break;
    }
    case 'getall': {
        const { limit, offset } = sanitizePaginationParams(body.limit, body.offset);

        let selectFields = buildSelectFields();
        // 🚀 HOTFIX ARQUITECTÓNICO 1: Sobrescribir el Rol global con el Rol del Tenant
        if (table === 'users') {
            selectFields = selectFields.replace(`${table}.*`, `${table}.*, uc.role`);
        }

        let baseQuery = `SELECT ${selectFields} FROM ${table} ${buildJoins()}`;
        let whereParts = [];
        let paramIndex = 1;

        // 🚀 HOTFIX ARQUITECTÓNICO 2: Inyectar JOIN con tabla pivote para Multi-Tenancy
        if (table === 'users') {
            if (!baseQuery.includes('user_companies')) {
                baseQuery += ` INNER JOIN user_companies uc ON ${table}.email = uc.email`;
            }
        }

        Object.entries(fields).forEach(([key, value]) => {
            const isAllowed = (config.allowed_fields || []).includes(key);

            if (isAllowed && key !== 'limit' && key !== 'offset') {
                let dbColumn = `${table}.${key}`;

                // Redirección del filtro hacia la tabla pivote
                if (table === 'users' && key === 'tenant_id') {
                    dbColumn = 'uc.id_company';
                } else if (key === 'created_at' || key === 'check_in') {
                    dbColumn = `(${table}.${key} - INTERVAL '6 hours')::date`;
                }

                if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
                    Object.entries(value).forEach(([op, val]) => {
                        const sqlOp = op === '_gte' ? '>=' : op === '_lte' ? '<=' : op === '_gt' ? '>' : op === '_lt' ? '<' : '=';
                        const isDateLike = typeof val === 'string' && (val.includes('T') || /^\d{4}-\d{2}-\d{2}$/.test(val));

                        // 🛡️ PATCH 1: Evita que basura intente evaluarse como fecha en un objeto
                        if ((key === 'created_at' || key === 'check_in' || key === 'check_out') && !isDateLike) return;

                        if (isDateLike && key !== 'created_at' && key !== 'check_in') {
                             whereParts.push(`${dbColumn}::date ${sqlOp} $${paramIndex++}::date`);
                             values.push(val.split('T')[0]);
                        } else {
                             whereParts.push(`${dbColumn} ${sqlOp} $${paramIndex++}`);
                             values.push(val);
                        }
                    });
                } else if (value !== undefined && value !== '' && value !== null) {
                    const isDateLike = typeof value === 'string' && (value.includes('T') || /^\d{4}-\d{2}-\d{2}$/.test(value));

                    // 🛡️ PATCH 2: Evita el colapso de Postgres si el frontend manda texto en campos de fecha
                    if ((key === 'created_at' || key === 'check_in' || key === 'check_out') && !isDateLike) return;

                    if (isDateLike && key !== 'created_at' && key !== 'check_in') {
                        whereParts.push(`${dbColumn}::date = $${paramIndex++}::date`);
                        values.push(value.split('T')[0]);
                    } else {
                        whereParts.push(`${dbColumn} = $${paramIndex++}`);
                        values.push(value);
                    }
                } else if (value === null) {
                    whereParts.push(`${dbColumn} IS NULL`);
                }
            }
        });

        // 🛡️ FIX: Resolver la Ambigüedad de la columna is_active en el default_filter
        if (config.default_filter && !fields.hasOwnProperty('is_active') && !config.default_filter.includes('$1')) {
            let defFilter = config.default_filter;
            if (table === 'users' && defFilter.includes('is_active')) {
                defFilter = defFilter.replace('is_active', `${table}.is_active`);
            }
            whereParts.push(defFilter);
        }

        if (whereParts.length > 0) baseQuery += ` WHERE ${whereParts.join(' AND ')}`;

        let sortCol = body.sort_by ? body.sort_by : (fields.published_at ? 'published_at' : 'created_at');
        // SECURITY: the sort column is interpolated into ORDER BY; allow plain identifiers only.
        if (typeof sortCol !== 'string' || !/^[A-Za-z_][A-Za-z0-9_]{0,62}$/.test(sortCol)) {
            throw new Error('Columna de ordenamiento inválida.');
        }
        let finalSortCol = (table === 'users' && sortCol === 'tenant_id') ? 'uc.id_company' : `${table}.${sortCol}`;

        baseQuery += ` ORDER BY ${finalSortCol} DESC NULLS LAST LIMIT $${paramIndex++} OFFSET $${paramIndex++};`;

        query = baseQuery;
        values.push(limit, offset);
        break;
    }
    case 'delete': {
        const pkField = config.primary_key || 'id';
        const idValue = body[pkField] || fields[pkField] || body.id || fields.id;
        if (!idValue) throw new Error(`DELETE requiere el valor de ${pkField}`);

        // 🛡️ SECURITY PATCH: Aislamiento Multi-Tenant en DELETE (soft-delete)
        // Antes: cualquier tenant podía desactivar un registro de otro solo conociendo su id.
        let whereParts = [`${pkField} = $1`];
        values = [idValue];

        // Excepción: 'users' resuelve tenant vía tabla pivote (user_companies), no aplica aquí.
        if (table !== 'users') {
            if (tenantIdHeader && modelHasTenantId) {
                whereParts.push(`tenant_id = $2`);
                values.push(tenantIdHeader);
            } else if (tenantIdHeader && modelHasIdCompany) {
                whereParts.push(`id_company = $2`);
                values.push(tenantIdHeader);
            }
        }

        query = `UPDATE ${table} SET is_active = false WHERE ${whereParts.join(' AND ')} RETURNING *;`;
        break;
    }
    case 'getone': {
        const pkField = config.primary_key || 'id';
        let val = fields[pkField] || body[pkField] || body.id || fields.id || fields.email || body.email;
        let searchField;

        if (!val && Object.keys(fields).length > 0) {
            searchField = Object.keys(fields)[0];
            val = fields[searchField];
        } else if (val) {
            searchField = (fields.email || body.email) && !fields[pkField] ? 'email' : pkField;
        }
        if (!val) throw new Error(`GETONE requiere un ID o un campo de búsqueda.`);
        // SECURITY: the search field is interpolated into WHERE; allow plain identifiers only.
        if (!/^[A-Za-z_][A-Za-z0-9_]{0,62}$/.test(String(searchField))) {
            throw new Error('Campo de búsqueda inválido.');
        }

        // 🛡️ SECURITY PATCH: Aislamiento Multi-Tenant en GETONE
        // Antes: cualquier tenant podía leer un registro de otro solo conociendo su id/campo de búsqueda.
        let whereParts = [`${table}.${searchField} = $1`];
        values = [val];

        // Excepción: 'users' resuelve tenant vía tabla pivote (user_companies), no aplica aquí.
        if (table !== 'users') {
            if (tenantIdHeader && modelHasTenantId) {
                whereParts.push(`${table}.tenant_id = $2`);
                values.push(tenantIdHeader);
            } else if (tenantIdHeader && modelHasIdCompany) {
                whereParts.push(`${table}.id_company = $2`);
                values.push(tenantIdHeader);
            }
        }

        query = `SELECT ${buildSelectFields()} FROM ${table} ${buildJoins()} WHERE ${whereParts.join(' AND ')} LIMIT 1;`;
        break;
    }
    case 'call_sp': {
        // Configuración por modelo: orden exacto de parámetros de negocio (sin tenant_id)
        // y en qué posición (0-indexed, ANTES de insertar) va el tenant en la firma real de Postgres.
        const spConfigByModel = {
            'sp_procesar_salida_ganado': {
                paramOrder: ['electronic_rfid', 'rfid_siniiga', 'numero_fuego', 'livestock_id'],
                tenantPosition: 1
            },
            'sp_register_birth_event': {
                paramOrder: ['calf_sex', 'species', 'dam_id', 'dam_ear_tag', 'dam_fire_number', 'birth_date', 'lot_id', 'production_unit_id', 'paddock_id', 'birth_weight_kg', 'notes'],
                tenantPosition: 0
            },
            'sp_procesar_baja_mortandad': {
                paramOrder: ['electronic_rfid', 'rfid_siniiga', 'numero_fuego', 'causa_mortandad', 'fecha_evento', 'descripcion', 'reportado_por_email', 'autorizado_por_email'],
                tenantPosition: 3  // p_electronic_rfid(0), p_rfid_siniiga(1), p_numero_fuego(2), p_tenant_id(3) → 4to parámetro
            },
            'sp_solicitar_autorizacion': {
                paramOrder: ['electronic_rfid', 'rfid_siniiga', 'numero_fuego', 'livestock_id', 'tipo_evento', 'payload', 'solicitado_por_email'],
                tenantPosition: 4,  // p_electronic_rfid(0), p_rfid_siniiga(1), p_numero_fuego(2), p_livestock_id(3), p_tenant_id(4)
                actorEmailField: 'solicitado_por_email'
            },
            'sp_resolver_autorizacion': {
                paramOrder: ['request_id', 'decision', 'resuelto_por_email', 'notas'],
                tenantPosition: null,  // tenant/role are validated inside the SP (fn_is_active_company_admin)
                actorEmailField: 'resuelto_por_email'
            },
            'sp_cancelar_autorizacion': {
                paramOrder: ['request_id', 'cancelado_por_email', 'motivo'],
                tenantPosition: 1,  // p_request_id(0), p_tenant_id(1)
                actorEmailField: 'cancelado_por_email'
            }
        };

        const spConfig = spConfigByModel[table];
        if (!spConfig) {
            throw new Error(`No hay configuración de parámetros para el procedimiento ${table}`);
        }

        const requiresTenant = config.sp_requires_tenant !== false;
        // 🛡️ SECURITY: actor identity always comes from the verified JWT; any client-supplied email is overwritten.
        if (spConfig.actorEmailField) {
            if (!config.user_email) {
                throw new Error('Authenticated user email is required for this procedure');
            }
            fields[spConfig.actorEmailField] = config.user_email;
        }
        const values_sp = spConfig.paramOrder.map(p => fields[p] ?? null);

        if (requiresTenant) {
            if (!tenantIdHeader) throw new Error('tenant_id requerido para ejecutar este procedimiento almacenado');
            values_sp.splice(spConfig.tenantPosition, 0, parseInt(tenantIdHeader, 10));
        }

        const placeholders = values_sp.map((_, i) => `$${i + 1}`);
        query = `SELECT ${table}(${placeholders.join(', ')}) AS resultado;`;
        values = values_sp;
        break;
    }

}

return [{ json: { query, values, operation, is_transactional: ['insert', 'update', 'delete'].includes(operation) } }];

// Recuperamos los datos ejecutados
const sqlResults = $input.all().map(item => item.json); 
const config = $('Security Validation').first().json;
const operation = (config.operation || '').toLowerCase();

// Validamos si Postgres tiró error (continueOnFail)
if (sqlResults.length > 0 && sqlResults[0].error) {
    return [{
        json: {
            error: true,
            operation,
            message: sqlResults[0].message || "Error al ejecutar consulta en base de datos",
            data: null
        }
    }];
}

// Filtramos filas reales (evitamos metadatos vacíos si los hay)
// SECURITY: credential columns must never leave the gateway (covers SELECT *, RETURNING *
// and nested row_to_json() join payloads such as <table>_data).
const SENSITIVE_KEYS = new Set(['password']);
const isPlainObject = (v) => Object.prototype.toString.call(v) === '[object Object]';
const stripSensitive = (v) => {
  if (Array.isArray(v)) return v.map(stripSensitive);
  if (isPlainObject(v)) {
    const out = {};
    for (const k of Object.keys(v)) {
      if (!SENSITIVE_KEYS.has(k)) out[k] = stripSensitive(v[k]);
    }
    return out;
  }
  return v;
};

const rows = sqlResults
  .filter(row => row && typeof row === 'object' && !row.hasOwnProperty('success'))
  .map(stripSensitive);

let data = rows;
let resultStatus = "success";
let message = "Ejecución satisfactoria";
let foundRecords = rows.length;

// Lógica de Normalización
switch (operation) {
  case 'getone':
    if (rows.length === 0) {
      data = null; resultStatus = "error"; message = "Registro no encontrado."; foundRecords = 0;
    } else {
      data = rows[0]; foundRecords = 1;
    }
    break;
  case 'update':
    if (rows.length === 0) {
      data = []; resultStatus = "error"; message = "No se actualizó ningún registro. Verifica el ID."; foundRecords = 0;
    }
    break;
  case 'delete':
    if (rows.length === 0) {
      data = []; resultStatus = "error"; message = "No se pudo eliminar. El registro no existe."; foundRecords = 0;
    } else {
      message = "Registro eliminado con éxito.";
    }
    break;
  case 'getall':
    data = rows; foundRecords = rows.length;
    break;
  case 'insert':
    data = rows[0] || rows; foundRecords = rows.length;
    break;
  case 'call_sp':
    data = rows[0]?.resultado ?? null;
    foundRecords = data ? 1 : 0;
    break;
}

const postHooks = (resultStatus === "success" && config.hooks?.post) ? config.hooks.post : [];

return [{
  json: {
    error: resultStatus !== "success",
    operation,
    message,
    data,
    execution_info: {
      timestamp: new Date().toISOString(),
      model: config.model_name,
      has_post_hooks: postHooks.length > 0
    }
  }
}];
